(7699457, 1263551, 173844, '<td valign="top">The entry most evocative of the style, in my opinion.  The processing beautifully exaggerates the colors, textures and highlights.  Her pose and mien are spot on, and the aqua faced cell phone is a lovely, apt touch.  A tour de force.<br/>Personal favorite of the challenge.</td>', 'The entry most evocative of the style, in my opinion.  The processing beautifully exaggerates the colors, textures and highlights.  Her pose and mien are spot on, and the aqua faced cell phone is a lovely, apt touch.  A tour de force.Personal favorite of the challenge.', '2021-08-22 23:27:44.000000', NULL, 1),
(7699458, 1263530, 173844, '<td valign="top">At once charmed and mystified, and delighted that''s it''s in black and white.  Those skinny limbs do the style proud.  He goest through time''s wall.</td>', 'At once charmed and mystified, and delighted that''s it''s in black and white.  Those skinny limbs do the style proud.  He goest through time''s wall.', '2021-08-22 23:37:28.000000', NULL, 1),
(7699459, 1263533, 173844, '<td valign="top">The title says it.  A nonchalant mannerist pose, and the golden (sort of) curls of a Renaissance child.  Beautifully seen.</td>', 'The title says it.  A nonchalant mannerist pose, and the golden (sort of) curls of a Renaissance child.  Beautifully seen.', '2021-08-22 23:40:41.000000', NULL, 1),
(7699460, 1263402, 173844, '<td valign="top">Handsomely done. Is this a photo or a painting, it''s that good.</td>', 'Handsomely done. Is this a photo or a painting, it''s that good.', '2021-08-22 23:41:51.000000', NULL, 1),
(7699461, 1263550, 173844, '<td valign="top">A funky go at the style, but works in a cunning fashion.</td>', 'A funky go at the style, but works in a cunning fashion.', '2021-08-22 23:43:11.000000', NULL, 1),
